  "upgrade.upgradeNeverRestartsTrial": "Ein Upgrade startet Ihre kostenlose Testphase niemals neu.",
  "upgrade.trialHistoryNote": "Wenn Sie für Essentials zahlen und zu Business wechseln, behalten Sie dasselbe Kundenkonto und dieselbe Testphasen-Historie. Business enthält keine zusätzliche siebentägige Testphase. Wenn Sie upgraden, während Ihre ursprüngliche Testphase noch läuft, wird ihr ursprüngliches Enddatum nicht zurückgesetzt.",
  "upgrade.providerConfirmNote": "Planänderungen erfordern eine Bestätigung des Abrechnungsanbieters. Preisdifferenz, anteilige Berechnung und Wirksamkeitsdatum müssen angezeigt werden, bevor Sie die Änderung genehmigen. Ein Upgrade darf kein zweites gleichzeitiges Abonnement erstellen.",
  "upgrade.chargedThroughProviderNote": "Planänderungen werden über den Abrechnungsanbieter berechnet. Sie können Ihr Abonnement von dieser Seite aus kündigen, indem Sie die Schaltfläche „Abonnement kündigen“ unter Ihrem aktuellen Plan verwenden, oder über die Einstellungen. Eine Kündigung stoppt zukünftige Verlängerungen zum Ende Ihres bezahlten Zeitraums; sie beendet Ihren Zugriff niemals sofort. Bestehende kostenlose Arbeitsbereiche werden durch das Ansehen dieser Optionen nicht berechnet.",
  "billing.cancel.title": "Abonnement kündigen",
  "billing.cancel.description": "Kündigen Sie {plan}. Eine Kündigung stoppt zukünftige Verlängerungen zum Ende Ihres bezahlten Zeitraums — sie beendet Ihren Zugriff niemals sofort.",
  "billing.cancel.yourPlan": "Ihren Plan",
  "billing.cancel.doneTitle": "Ihr Abonnement ist gekündigt.",
  "billing.cancel.doneWithEnd": "Sie behalten vollen Zugriff bis zum {endDate}. Nach diesem Datum haben Sie eine {graceDays}-tägige schreibgeschützte Kulanzfrist — Sie können sich weiterhin anmelden und Ihre Produkte sehen, aber Sie können nichts hinzufügen, bearbeiten, löschen, scannen, importieren, exportieren oder ändern. {gracePart}",
  "billing.cancel.graceEndsOn": "Nach Ablauf der 15-tägigen Kulanzfrist am {date} werden Ihr Konto und alle Ihre Informationen endgültig gelöscht und können nicht wiederhergestellt werden.",
  "billing.cancel.doneNoEnd": "Sie behalten vollen Zugriff bis zum Ende Ihres bezahlten Zeitraums. Danach gilt eine 15-tägige schreibgeschützte Kulanzfrist. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Sie haben innerhalb von 3 Tagen nach Ihrer ersten bezahlten Gebühr gekündigt, daher haben Sie möglicherweise Anspruch auf eine Erstattung dieser ersten Zahlung. Die Kündigung selbst löst die Erstattung nicht aus — beantragen Sie sie über {contact}.",
  "billing.cancel.refundWindowClosed": "Eine Kündigung allein löst keine Erstattung aus. Erstattungen gelten nur innerhalb von 3 Tagen nach der ersten erfolgreichen bezahlten Gebühr, beantragt über {contact}.",
  "billing.cancel.notCanceledTitle": "Ihr Abonnement wurde NICHT gekündigt.",
  "billing.cancel.contactCode": "Wenn Sie sich an {contact} wenden, nennen Sie diesen Code: {code}",
  "billing.cancel.alreadyCanceledTitle": "Dieses Abonnement ist bereits gekündigt.",
  "billing.cancel.alreadyCanceledWithEnd": "Es endet am {date}. Sie behalten bis dahin vollen Zugriff. Nach diesem Datum haben Sie eine {graceDays}-tägige schreibgeschützte Kulanzfrist, um Ihre Produkte zu sehen. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "Es endet am Ende des aktuellen bezahlten Zeitraums. Sie behalten bis dahin vollen Zugriff.",
  "billing.cancel.appStoreNote": "Wenn Sie jemals über Google Play oder den Apple App Store abonnieren, müssen Sie es möglicherweise über die Abonnement-Einstellungen dieses Stores kündigen. Dieser Dialog kann die Abrechnung über den App-Store nicht stoppen. Das Deinstallieren der App oder das Löschen Ihres StockHaven-Kontos kündigt kein Store-Abonnement.",
  "billing.cancel.trialNote": "Eine Kündigung während Ihrer Testphase behält Ihre vollen 7 Tage — der Zugriff endet am {date}, und Ihnen wird nichts berechnet.",
  "billing.cancel.trialNoteNoDate": "Eine Kündigung während Ihrer Testphase behält Ihre vollen 7 Tage, und Ihnen wird nichts berechnet.",
  "billing.cancel.keepAccessUntil": "Sie behalten vollen Zugriff bis zum {date}.",
  "billing.cancel.endOfPaidPeriod": "das Ende Ihres bezahlten Zeitraums",
  "billing.cancel.keepAccessRest": "Eine Kündigung stoppt nur zukünftige Verlängerungen — sie beendet Ihren Zugriff niemals sofort, und es wird kein zusätzlicher kostenloser Monat hinzugefügt.",
  "billing.cancel.gracePeriodTitle": "Nach diesem Datum eine {graceDays}-tägige schreibgeschützte Kulanzfrist.",
  "billing.cancel.gracePeriodRest": "Sie können sich weiterhin anmelden und Ihre Produkte sehen, sodass Sie sich ansehen können, was Sie hatten, und es aufschreiben. Alles andere ist gesperrt: kein Hinzufügen, Bearbeiten, Löschen, Scannen, Importieren, Exportieren oder Migrieren, keine Einstellungen, keine Mitarbeiter.",
