  "billing.cancel.refundsRest": "Eine Kündigung allein löst keine Erstattung aus. Eine Erstattung der ersten Zahlung gilt nur, wenn Sie innerhalb von 3 Tagen (72 Stunden) nach der ersten erfolgreichen bezahlten Gebühr kündigen, beantragt über {contact}.",
  "billing.cancel.oneTrialTitle": "Eine kostenlose Testphase.",
