  "exports.eyebrow": "Daten",
  "exports.title": "Exporte & Sicherungen",
  "exports.subtitleStart": "Downloads sind immer begrenzt auf",
  "exports.subtitleRest": ". Jede Datei ist mit dem Unternehmensnamen und dem Erstellungsdatum gekennzeichnet.",
  "exports.createBusinessFirst": "Erstellen Sie zuerst ein Unternehmen — Exporte gehören zu einem Unternehmen, nicht zur App.",
  "exports.lockedTitle": "CSV- und Excel-Exporte sind eine Business-Funktion",
  "exports.lockedDesc": "Ihr Arbeitsbereich nutzt den Essentials-Plan. Business fügt CSV- und Excel-Exporte, Bestandsbewertung, unbegrenzte Produkte und Mitarbeiter, Lieferanten, Einkauf und Bundles hinzu.",
  "exports.seeBusiness": "Sehen, was Business enthält",
  "exports.whatTheseAre": "Was diese Dateien sind",
  "exports.about1": "Jeder Datensatz kommt als CSV oder als echte Excel-Arbeitsmappe (.xlsx) — die vollständige Bestandsarbeitsmappe ist nur als Excel verfügbar, mit einem Blatt pro Datensatz. CSV-Dateien lassen sich in Excel, Numbers, Google Tabellen und den meisten Bestands-Apps öffnen. UTF-8-Text, Kommas in Anführungszeichen, Zeilenumbrüche in Notizen und führende Nullen in Codes bleiben alle erhalten, und Zellen, die wie eine Formel beginnen, werden neutralisiert, sodass eine Tabelle sie als Text öffnet.",
  "exports.about2": "In den Excel-Dateien sind SKUs, UPCs, ISBNs und Barcodes Textzellen — niemals wissenschaftliche Notation und niemals gekürzte Nullen — mit Spaltenbreiten, Kopffiltern und Währungs- oder Mengenformaten. Die vollständige Bestandsarbeitsmappe hält Produkte, Bestände, Standorte und Bewegungen auf getrennten Blättern.",
  "exports.about3": "Sehr große Exporte stoppen bei 20.000 Zeilen pro Datensatz — wenn das passiert, sagt der Dateiname es (truncated-20000), sodass eine Teil-Datei niemals als vollständig durchgeht.",
  "exports.about4": "Eine Sicherung ist eine Momentaufnahme Ihrer Daten, keine Wiederherstellung mit einem Klick. Das Wiederherstellen ist eine manuelle Aufgabe mit vorheriger Prüfung, bewahren Sie die Datei also sicher auf — nichts in der App kann ein gelöschtes Unternehmen daraus bisher wiederherstellen. App-Code und Base44-Plattformsicherungen werden getrennt von diesen Dateien gehandhabt.",
  "exports.about5": "Fotos und Anhänge werden als ihre gespeicherten Links aufgeführt — die Bilddateien selbst sind nicht im Download enthalten.",
  "exports.backupTitle": "Vollständige Sicherung",
  "exports.backupDesc": "Eine Datei mit den Produkten, Standorten, Beständen, dem vollständigen Bewegungsjournal, Lieferanten, Einkauf, Aufträgen, Retouren, Zählungen und Angeboten dieses Unternehmens — plus seinen Profileinstellungen. Bewahren Sie sie an einem Ort auf, den Sie kontrollieren.",
  "exports.backupIncludes1": "Produkte, Codes, Kosten und Notizen",
  "exports.backupIncludes2": "Standorte und Mengen pro Standort",
  "exports.backupIncludes3": "Jede Bewegung, mit Akteur und Zeitpunkt",
  "exports.backupIncludes4": "Einkauf, Aufträge, Retouren und Zählungen",
  "exports.buildingBackup": "Sicherung wird erstellt…",
  "exports.backupJson": "Sicherung (JSON)",
  "exports.excelSnapshot": "Excel-Momentaufnahme",
