  "import.eyebrow": "Daten",
  "import.title": "Importcenter",
  "import.subtitleStart": "Drei getrennte Tabellenvorgänge, sodass eine Preiskorrektur niemals als Wareneingang ankommen kann. Alles landet in",
  "import.subtitleRest": " nur, und nichts wird geschrieben, bis ein Probelauf bestanden ist.",
  "import.createBusinessFirst": "Erstellen Sie zuerst ein Unternehmen — importierte Produkte gehören zu einem Unternehmen.",
  "import.createBusinessFirstShort": "Erstellen Sie zuerst ein Unternehmen.",
  "import.whatEachDoes": "Was jeder Vorgang tut",
  "import.createTitle": "Neue Produkte erstellen",
  "import.createDesc": "fügt Zeilen hinzu, die noch nicht im Katalog sind. Doppelte SKUs und Barcodes, die bereits verwendet werden, werden übersprungen, und Anfangsbestand kann als Wareneingang an einem von Ihnen gewählten Standort landen.",
  "import.updateTitle": "Bestehende Produkte aktualisieren",
  "import.updateDesc": "gleicht jede Zeile nach SKU oder Datensatz-ID ab und zeigt den alten Wert neben dem vorgeschlagenen neuen an. Leere Zellen lassen den gespeicherten Wert in Ruhe, es sei denn, Sie bitten darum, leere Felder zu löschen, und Mengen werden niemals berührt.",
  "import.receiveModeTitle": "Ware entgegennehmen",
  "import.receiveModeDesc": "fügt eingehende Mengen an einem Standort hinzu und schreibt für jede Zeile einen Wareneingang ins Bewegungsjournal. Jeder Stapel ist markiert, sodass dasselbe Blatt nicht zweimal entgegengenommen werden kann.",
  "import.excelNote": "Excel-Arbeitsmappen (.xlsx) werden direkt gelesen — wählen Sie das Arbeitsblatt und die Spalten werden für Sie abgeglichen. Codes bleiben vollständig: Eine als Text gespeicherte UPC behält ihre Ziffern und führenden Nullen. Zeilen, die nicht importiert werden können, werden mit einem Grund aufgelistet",
