  "reports.title": "Berichte",
  "reports.subtitle": "Wählen Sie, was Sie ansehen möchten, wie es gruppiert wird und über welchen Zeitraum. Jede Zahl wird aus Ihren eigenen Bestands- und Bewegungsdaten gezählt, und die Tabelle kann als Datei heruntergeladen werden.",
