  "reports.missingMoney": "{units} Einheiten in dieser Ansicht haben keinen {label} erfasst. Fehlendes Geld wird niemals als null behandelt — sie werden aus den Zahlen herausgelassen, statt als kostenlos gezählt. Fügen Sie die Zahl auf diesen Produkten hinzu und die Summen füllen sich.",
  "reports.movementsCapped": "Nur die neuesten {cap} Journaleinträge wurden gelesen, sodass ältere Bewegungen nicht in den Summen sind. Engen Sie den Zeitraum ein, um genaue Zahlen für ein Fenster zu sehen.",
  "reports.footnote": "Verkäufe verwenden den aktuellen Verkaufspreis jedes Produkts, Wareneingänge die Kosten, die bei der Ankunft der Ware erfasst wurden, und Verluste die aktuellen Stückkosten. Fehlendes Geld wird niemals als null behandelt — lassen Sie eine Zahl leer, bis sie bekannt ist. Ein Bericht ist eine Ansicht, kein Dokument: Es wird nichts in Ihre Daten geschrieben, wenn Sie einen ausführen.",
