  "valuation.noRetailPrice": "kein Verkaufspreis",
  "valuation.footnote": "Der Kostenwert verwendet die aktuellen Stückkosten jedes Produkts, sodass ein Wareneingang zu einem neuen Preis das ganze Regal neu bewertet. Reservierte Einheiten werden hier weiterhin gezählt — sie sind vorrätig, nur für einen Auftrag versprochen. Fehlendes Geld wird niemals als null behandelt; lassen Sie ein Feld leer, bis die Zahl bekannt ist.",
