  "print.templateIsBusiness": "{label} ist eine Business-Funktion",
  "print.supplierBlockedDesc": "Lieferantendokumente gehören zum Business-Plan — Lieferanten, Einkauf und Bestellungen. Alles, was Sie jetzt haben, funktioniert weiter.",
  "print.seeBusiness": "Sehen, was Business enthält",
  "print.nothingToPrint": "Noch nichts zu drucken",
  "print.pickOrderHint": "Wählen Sie eine Bestellung aus der Liste, um das Dokument in der Vorschau zu sehen.",
  "print.pickCustomerOrderHint": "Wählen Sie einen Kundenauftrag aus der Liste, um das Dokument in der Vorschau zu sehen.",
  "print.pickReturnHint": "Wählen Sie eine erfasste Retoure aus der Liste, um das Dokument in der Vorschau zu sehen.",
  "print.chooseStyleHint": "Wählen Sie einen Stil und dann Produkte aus der Liste. Die Vorschau zeigt genau, was aus dem Drucker kommt.",
  "print.howToReach": "So erreichen Sie Ihren Drucker",
  "print.howIntro": "Diese App verbindet sich mit Druckern, die Sie bereits besitzen — sie ist selbst kein Drucker. Es gibt vier Wege zu einem, und Etiketten drucken auf beiden Plänen über jeden davon. Packzettel, Bestellungen, Lieferantendokumente und Berichte sind Business-only, egal über welche Verbindung.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "Von dieser Seite aus, in Desktop-Chrome oder Edge und in Android-Chrome: Wählen Sie Ihren Etikettendrucker und die Etiketten gehen direkt dorthin. Es funktioniert nicht in iOS Safari — auf einem iPhone kommt Bluetooth-Drucken stattdessen mit der mobilen App. Ein Drucker, der nur Zebra ZPL oder die eigene Sprache von Brother spricht, versteht die Etiketten nicht, die diese Seite sendet; das wird vor der Freigabe an echten Druckern geprüft.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "Installieren Sie den Drucker im Wi-Fi Ihres Geschäfts und verwenden Sie dann die Schaltfläche „Drucken“ — der Druck erfolgt über den auf diesem Computer installierten Drucker, über das Geschäftsnetzwerk. Auf einem iPhone ist AirPrint eingebaut: Ein AirPrint-Drucker im selben Wi-Fi erscheint einfach im Druckblatt, ohne Kabel und ohne App, und die App braucht keinen AirPrint-spezifischen Code. Der Drucker muss AirPrint unterstützen (die meisten neuen tun das) und Smartphone und Drucker müssen im selben Wi-Fi sein.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "Verkabeln Sie den Drucker mit einem Ethernet-Kabel mit Ihrem Geschäftsnetzwerk, installieren Sie ihn auf dem Computer und drucken Sie über die Schaltfläche „Drucken“. Ethernet ist ein Desktop- und Computerweg — iPhones verwenden keine Ethernet-Kabel.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "Schließen Sie den Drucker mit seinem Kabel an den Computer an und verwenden Sie die Schaltfläche „Drucken“ — der Druck erfolgt über den dort installierten Drucker. Auf einem Android-Smartphone mit einem USB-OTG-Kabel spricht die USB-Schaltfläche oben direkt mit dem Drucker. iPhones können nicht direkt über USB drucken — dort gibt es kein WebUSB — nutzen Sie also Wi-Fi / AirPrint oder Bluetooth aus der mobilen App.",
  "print.howCordsLead": "Kabel dienen iPhones weiterhin, einen Schritt entfernt.",
  "print.howCordsBody": "Ein USB-Drucker, der an den Geschäftscomputer angeschlossen ist, oder ein Ethernet-Drucker, der mit dem Netzwerk verkabelt ist, erscheint auf Ihrem iPhone über das Geschäfts-Wi-Fi (AirPrint / freigegebener Drucker) — die Kabel bringen den Drucker solide ins Netzwerk, und das Smartphone erreicht ihn drahtlos.",
  "print.howOfflineLead": "Wenn das Internet ausfällt,",
  "print.howOfflineBody": "drucken die Etiketten und Dokumente, die bereits auf dieser Seite sind, weiterhin — die Schaltfläche „Drucken“, das Etiketten-PDF, Bluetooth und USB brauchen keine Verbindung. Was das Internet braucht, ist das erstmalige Laden der Seite und ihrer Produkte. Der vollständige Offline-Modus (Arbeiten in der App ganz ohne Verbindung) ist ein separates, größeres Projekt und wird hier nicht behauptet.",
