  "settings.cancelSubscription": "Abonnement kündigen",
  "settings.cancelTerms.appleLink": "Apple-Anleitung zur Kündigung",
  "settings.cancelTerms.googlePlayLink": "Google-Play-Anleitung zur Kündigung",
  "settings.cancelTerms.graceTitle": "Nach Ende Ihres bezahlten Zeitraums — 15 Tage Kulanz, dann Löschung:",
  "settings.cancelTerms.intro": "Dies sind die Bedingungen für bezahlte Luminous StockHaven-Abonnements. Die Abrechnung von Website-Abonnements erfolgt über Stripe. Sie können Ihr Abonnement jederzeit selbst mit der Schaltfläche „Abonnement kündigen“ unten kündigen — es ist keine Genehmigung durch Mitarbeiter erforderlich. Kündigungs- und Erstattungsanfragen können auch über den offiziellen Kundensupport-Kontakt theluminousbookshop@outlook.com bearbeitet werden.",
  "settings.cancelTerms.noApprovalBody": "Sie können Ihr Abonnement jederzeit selbst kündigen. Es ist keine Genehmigung durch Mitarbeiter erforderlich. Zukünftige Verlängerungen stoppen erst, nachdem der Abrechnungsanbieter die Kündigung bestätigt hat.",
  "settings.cancelTerms.noApprovalTitle": "Kündigen ohne Genehmigung:",
  "settings.cancelTerms.paymentBody": "Bei bezahlten Testphasen erfordert die siebentägige Testphase bei der Anmeldung eine Zahlungsmethode. Sofern nicht innerhalb der geltenden Kündigungsfrist der Testphase gekündigt wird, wird der gewählte Monatsplan nach der Testphase automatisch berechnet. Preis, erstes Abrechnungsdatum und die anbieterspezifische Kündigungsfrist müssen bei der Anmeldung angezeigt werden. Die Abrechnung der Testphase erfolgt über Stripe.",
  "settings.cancelTerms.paymentTitle": "Zahlungsmethode und automatische Verlängerung:",
  "settings.cancelTerms.remainingBody": "Wenn Sie einen Abrechnungszeitraum bereits bezahlt haben, können Sie den Zugriff bis zu diesem geprüften Bezahlt-bis-Datum behalten. Eine frühere Beendigung erfordert eine entsprechende Bestätigung des Anbieters und eine etwaige Erstattungsbearbeitung. Der Zugriff auf die kostenlose Testphase endet gemäß dem vom Anbieter bestätigten Beendigungsdatum der Testphase.",
  "settings.cancelTerms.remainingTitle": "Verbleibender Zugriff:",
  "settings.cancelTerms.storesBody": "Wenn Sie jemals über Google Play oder den Apple App Store abonnieren, wird Ihr Abonnement von diesem Store abgerechnet und verwaltet. Möglicherweise müssen Sie es direkt im Abonnementbereich desselben Google- oder Apple-Kontos kündigen, das für das Abonnement verwendet wurde. Die Kündigung eines separaten Website-Abonnements, das Deinstallieren dieser App oder die Beantragung der Löschung Ihres Luminous StockHaven-Kontos kündigt ein über den Store abgerechnetes Abonnement nicht automatisch. Prüfen Sie Ihren Kaufbeleg, um zu bestätigen, wer Sie abrechnet.",
  "settings.cancelTerms.storesTitle": "Google Play- und Apple App Store-Abonnements (falls Sie jemals über einen Store abonnieren):",
  "settings.cancelTerms.title": "Kündigungsbedingungen",
  "settings.cancelTerms.trialBody": "Die siebentägige Testphase kann nur einmal pro berechtigtem Kunden genutzt werden. Die Kündigung einer Testphase oder eines Abonnements gewährt keine weitere Testphase; zurückkehrende Kunden müssen ein kostenpflichtiges Abonnement wählen.",
  "settings.cancelTerms.trialTitle": "Eine kostenlose Testphase:",
  "settings.canceled.endsOn": "Dieses Abonnement ist gekündigt und endet am {date}. Sie behalten bis dahin vollen Zugriff.",
  "settings.delete.checking": "Es wird geprüft, ob eine Löschungsanfrage vorliegt…",
  "settings.delete.description": "Beantragen Sie die Entfernung Ihres Luminous StockHaven-Anmeldekontos.",
  "settings.delete.dialogDescription": "Damit wird eine Prüfung der Kontolöschung beantragt. Es entfernt nicht sofort Ihre Anmeldung oder Ihren Bestand und kündigt kein Stripe-Abonnement. Geben Sie {word} ein, um zu bestätigen, dass Sie die Anfrage einreichen möchten.",
  "settings.delete.dialogTitle": "Kontolöschung beantragen",
  "settings.delete.enterDelete": "Geben Sie {word} ein, um zu bestätigen",
  "settings.delete.exportFirst": "Exportieren Sie zuerst Ihren Bestand, wenn Sie Ihre Daten behalten müssen.",
  "settings.delete.intro": "Das Einreichen einer Anfrage löscht Ihr Konto, Ihre Unternehmen oder Ihren Bestand nicht sofort. Anfragen werden separat geprüft, bevor eine Löschung abgeschlossen werden kann. Diese Anfrage kündigt kein Stripe-Abonnement und stoppt keine zukünftige Abrechnung; die Kündigung des Abonnements muss separat über den Abrechnungsanbieter abgewickelt werden.",
