  "staff.access.pendingTitle": "Ihre Einladung ist noch nicht aktiv",
  "staff.access.signOut": "Abmelden",
  "staff.access.suspendedBody": "Ein Administrator hat dieses Mitarbeiterkonto für das aktive Unternehmen gesperrt. Bitten Sie ihn, Sie wieder auf „aktiv“ zu setzen, und melden Sie sich dann erneut an.",
  "staff.access.suspendedTitle": "Ihr Zugriff ist pausiert",
  "staff.addFirst": "Fügen Sie den ersten Mitarbeiter hinzu",
  "staff.addMember": "Mitarbeiter hinzufügen",
  "staff.emptyBody": "Fügen Sie eine Person hinzu, geben Sie ihr eine Rolle und die dazugehörigen Berechtigungen, und sie wird per E-Mail eingeladen, sich bei diesem Unternehmen anzumelden.",
  "staff.emptyTitle": "Noch keine Mitarbeiter",
  "staff.eyebrow": "Team",
  "staff.how.p1": "Jedes Mitglied hat eine Rolle und eine eigene Berechtigungsliste, sodass Sie von einer Rolle ausgehen und eine Sache ändern können, ohne eine neue Rolle zu erstellen. Das Bearbeiten einer Rolle schreibt die Mitglieder, die bereits darauf sind, nicht neu — öffnen Sie ein Mitglied, um seine Rollenstandards erneut anzuwenden.",
  "staff.how.p2": "Benutzerdefinierte Rollen sind eine Business-Funktion: Essentials verwendet die fünf integrierten Rollen (Inhaber, Filialleiter, Lagerist, Verkäufer, Betrachter).",
  "staff.how.p3": "Einladungen werden per E-Mail gesendet. Ein Mitglied kann sich erst anmelden, wenn es annimmt, und das Entfernen einer Person aus dieser Liste löscht nicht ihr App-Konto.",
  "staff.how.p4": "Ein Geschäft ist der Standort, dem eine Person zugewiesen ist. Er wird auf ihrer Karte vermerkt; was sie öffnen kann, wird weiterhin durch ihre Rolle und Berechtigungen entschieden.",
  "staff.how.p5": "Berechtigungen entscheiden, was jede Person öffnen kann: Menüpunkte außerhalb ihrer Rolle sind ausgeblendet, und eine gesperrte Adresse zeigt statt der Seite einen Hinweis „nicht in Ihrer Rolle“. Eine Änderung gilt, wenn die Person die App das nächste Mal lädt; das Sperren eines Mitglieds schließt es vollständig aus.",
  "staff.how.p6": "Administratoren können alle Daten sehen und ändern, App-Benutzer und Rollen verwalten und werden niemals durch eine Mitarbeiterrolle eingeschränkt. Jemand ohne Mitarbeiterdatensatz — der Inhaber eines neuen Unternehmens — behält vollen Zugriff.",
  "staff.howTitle": "Wie Mitarbeiter und Rollen funktionieren",
