  "payroll.dd.steps.body": "1. Sie benötigen ein Geschäftskonto, das ACH-Zahlungen senden kann. 2. Holen Sie von jedem Teammitglied ein unterschriebenes Ermächtigungsformular ein — ein ungültig gemachter Scheck hilft, die Nummern zu überprüfen. 3. Senden Sie die Lohnabrechnung 2-3 Werktage vor dem Zahltag, damit das Geld rechtzeitig ankommt. 4. Die meisten Bundesstaaten verlangen die schriftliche Zustimmung des Teammitglieds. Diese App sammelt die Formulare und führt Sie durch die Schritte — das eigentliche Senden des Geldes erfolgt über Ihre eigene Bank.",
