  "workforce.todayShift": "Heutige Schicht: {start} - {end}",
  "workforce.unscheduledNote": "Für heute ist keine Schicht geplant, daher wird diese Zeit als nicht geplant markiert.",
  "workforce.inbox.help": "Stempelereignisse, Antworten zu freien Tagen, Aufgaben, Lohnabrechnungen und Dienstplanänderungen für Ihr Team, die neuesten zuerst.",
  "workforce.messages.back": "Alle Unterhaltungen",
  "workforce.messages.empty": "Noch keine Unterhaltungen. Beginnen Sie eine mit der Schaltfläche oben.",
  "workforce.messages.emptyThread": "Noch keine Nachrichten. Sagen Sie Hallo, um zu beginnen.",
  "workforce.messages.help": "Private Einzelgespräche mit Ihrem Team — keine andere App nötig. Nur die beiden Personen in einer Unterhaltung können sie lesen, plus der Geschäftsinhaber, der sein Geschäft beaufsichtigt.",
  "workforce.messages.new": "Neue Nachricht",
