  "training.newForYouHelp": "Diese Lektionen wurden hinzugefügt, weil Ihre Rolle gewachsen ist oder jemand sie Ihnen zugewiesen hat. Schließen Sie sie ab, um die neuen Teile der App zu lernen.",
