  "training.track.managerHelp": "Für die tägliche Teamführung: Dienstpläne, freie Tage, Aufgaben, Lohnabrechnungen und die Schulung Ihrer Mitarbeiter.",
  "training.track.owner": "Inhaber-Spur",
