  "training.track.staffHelp": "Die alltäglichen Werkzeuge: Scannen, die Zeiterfassung, Ihr Dienstplan, Ihr Posteingang und Ihre Lohnabrechnung.",
  "training.warningSentOn": "Warnung gesendet am {date}",
  "auth.sameEmailNotice": "Haben Sie unsere App bereits von Google Play oder dem App Store? Verwenden Sie hier dieselbe E-Mail — die, mit der Sie sich in der App anmelden — damit Ihr Geschäft und Ihr Bestand mit Ihnen kommen. Eine andere E-Mail startet ein völlig neues, leeres Geschäft.",
  "settings.deleteConfirmWord": "LÖSCHEN",
