  "workforce.tab.rewards": "Belohnungen",
  "training.lessons.mgr-give-rewards.step1": "Öffnen Sie Personal und tippen Sie auf Belohnungen. Wählen Sie das Teammitglied und dann die Art: Prozent Rabatt im Geschäft, eine Geschenkkarte oder etwas anderes, das Sie in Ihren eigenen Worten beschreiben.",
  "training.lessons.mgr-give-rewards.step2": "Geben Sie der Belohnung einen kurzen Namen und eine Notiz, wenn Sie möchten. Die Person erhält sofort eine Glocke, und die Belohnung wartet in ihren Meinen Belohnungen mit ihrem eigenen Code.",
  "training.lessons.mgr-give-rewards.step3": "Die Grenze, absichtlich: Sie belohnen NUR MITARBEITER. Sie können sich selbst oder eine andere Führungskraft nicht belohnen — eine Führungskraft zu belohnen ist die Entscheidung des Inhabers, und die App wird es klar verweigern.",
  "training.lessons.mgr-give-rewards.step4": "Tippen Sie an der Kasse den Code ein, den das Teammitglied Ihnen zeigt, und markieren Sie ihn als verwendet — jeder Code funktioniert einmal. Sie können eine von Ihnen gegebene Belohnung ungültig machen, wenn sich Pläne ändern; die Geschenke des Inhabers darf nur der Inhaber ungültig machen.",
  "training.lessons.mgr-give-rewards.title": "Belohnungen an Ihre Mitarbeiter geben",
  "training.lessons.owner-give-rewards.step1": "Belohnungen befinden sich in Personal, auf der Registerkarte Belohnungen, und sie sind nur im Business-Plan verfügbar — in Essentials zeigt die Registerkarte eine verschlossene Tür, sodass Ihr Team sehen kann, was der größere Plan bereithält.",
  "training.lessons.owner-give-rewards.step2": "Sie können JEDEN im Team belohnen — Mitarbeiter und Führungskräfte gleichermaßen. Wählen Sie die Person und dann die Art: Prozent Rabatt im Geschäft (jeder Prozentwert, den Sie wählen), eine Geschenkkarte für überall oder jeden Anreiz, den Sie in Ihren eigenen Worten beschreiben.",
  "training.lessons.owner-give-rewards.step3": "Die Belohnung landet mit ihrem eigenen Einmalcode und klingelt die Glocke der Person. Sie zeigt den Code an der Kasse; ein Inhaber oder eine Führungskraft tippt ihn ein, um ihn als verwendet zu markieren.",
  "training.lessons.owner-give-rewards.step4": "Ein gedruckter oder geteilter Belohnungszettel trägt nur den Namen IHRES Unternehmens — niemals den der App. Es ist das Dankeschön Ihres Geschäfts, keine Werbung.",
  "training.lessons.owner-give-rewards.title": "Belohnungen geben (Business-Plan)",
  "training.lessons.owner-rewards-oversight.step1": "Ihre Führungskraft kann ebenfalls Belohnungen geben — nur an Mitarbeiter. Die App verweigert es einer Führungskraft, sich selbst oder eine andere Führungskraft zu belohnen; eine Führungskraft zu belohnen ist immer Ihre Entscheidung.",
  "training.lessons.owner-rewards-oversight.step2": "Sie sehen jede Belohnung im Unternehmen im Belohnungsverlauf: wer sie gegeben hat, wer sie erhalten hat und ob sie bereit, verwendet oder ungültig ist. Eine Führungskraft sieht nur die Belohnungen, die sie gegeben hat, und die, die sie erhalten hat.",
  "training.lessons.owner-rewards-oversight.step3": "Sie können jede Belohnung ungültig machen, einschließlich einer, die Ihre Führungskraft gegeben hat. Eine Führungskraft kann ihre eigenen Geschenke ungültig machen, aber niemals Ihre.",
  "training.lessons.owner-rewards-oversight.step4": "Jeder Code funktioniert genau einmal, und eine ungültig gemachte Belohnung kann niemals verwendet werden — der Verlauf zeigt immer, wie eine Belohnung geendet hat.",
  "training.lessons.owner-rewards-oversight.title": "Belohnungen beaufsichtigen: das Geben Ihrer Führungskraft",
  "training.lessons.staff-your-rewards.step1": "Wenn Ihre Führungskraft oder der Inhaber Ihnen eine Belohnung gibt, klingelt Ihre Glocke. Öffnen Sie Personal und tippen Sie auf Belohnungen, um sie unter Meine Belohnungen zu sehen.",
  "training.lessons.staff-your-rewards.step2": "Jede Belohnung hat ihren eigenen Code. Behalten Sie ihn für sich — wer den Code an der Kasse zeigt, ist derjenige, der die Belohnung verwendet.",
  "training.lessons.staff-your-rewards.step3": "Um sie zu verwenden, zeigen Sie den Code beim Kauf. Die Person an der Kasse tippt ihn ein und markiert ihn als verwendet — jeder Code funktioniert genau einmal.",
  "training.lessons.staff-your-rewards.step4": "Belohnungen sind ein Leckerbissen des Business-Plans. Wenn Ihr Geschäft nicht in Business ist, zeigt die Registerkarte Belohnungen stattdessen eine verschlossene Tür — das ist der Plan, kein Fehler.",
  "training.lessons.staff-your-rewards.title": "Ihre Belohnungen: Ihren Code finden und verwenden",
  "training.module.rewards": "Belohnungen & Anreize",
