  "pos.events.heldPlanNote": "Einige Verkäufe unten kamen an, als dieses Geschäft nicht im Business-Plan war. Sie wurden sicher aufbewahrt, und nichts wurde gezählt. Jetzt, da das Geschäft in Business ist, können Sie sie zählen.",
